function Pill({ tone = "neutral", children }) {
  const tones = {
    neutral: { bg: "#EFEAD9", fg: "#5B5240" },
    good: { bg: "#E4EEE1", fg: "#33613F" },
    warn: { bg: "#F6E7D8", fg: "#8A5A22" },
    bad: { bg: "#F3E0DD", fg: "#8A2E24" },
    gold: { bg: "#FBF0D3", fg: "#8A6A0E" },
  };
  const t = tones[tone] || tones.neutral;
  return (
    <span
      style={{
        background: t.bg, color: t.fg, fontSize: 11.5, fontWeight: 700,
        padding: "3px 9px", borderRadius: 20, letterSpacing: 0.3,
        textTransform: "uppercase", whiteSpace: "nowrap",
      }}
    >
      {children}
    </span>
  );
}

function SectionCard({ title, eyebrow, right, children, style }) {
  return (
    <div
      style={{
        background: "#FFFFFF", border: "1px solid #E6DFCB", borderRadius: 10,
        boxShadow: "0 1px 2px rgba(41,33,15,0.04)", ...style,
      }}
    >
      {(title || right) && (
        <div
          style={{
            display: "flex", alignItems: "center", justifyContent: "space-between",
            padding: "16px 20px", borderBottom: "1px solid #EEE8D6",
          }}
        >
          <div>
            {eyebrow && (
              <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: 1.2, color: "#A6822B", textTransform: "uppercase", marginBottom: 3 }}>
                {eyebrow}
              </div>
            )}
            {title && (
              <h2 style={{ margin: 0, fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 19, color: "#26332C" }}>
                {title}
              </h2>
            )}
          </div>
          {right}
        </div>
      )}
      <div style={{ padding: 20 }}>{children}</div>
    </div>
  );
}

function SearchBox({ value, onChange, placeholder }) {
  return (
    <div style={{ position: "relative", width: 260 }}>
      <Search size={15} style={{ position: "absolute", left: 11, top: 10, color: "#9C8F6E" }} />
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder || "Search\u2026"}
        style={{
          width: "100%", padding: "8px 12px 8px 32px", borderRadius: 7,
          border: "1px solid #DED4B4", fontSize: 13.5, fontFamily: "'Inter', sans-serif",
          background: "#FBF9F2", outline: "none", color: "#26332C", boxSizing: "border-box",
        }}
      />
    </div>
  );
}

function Table({ columns, rows, keyField = "code", onRowClick }) {
  return (
    <div style={{ overflowX: "auto" }}>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13.5 }}>
        <thead>
          <tr>
            {columns.map((c) => (
              <th
                key={c.key}
                style={{
                  textAlign: c.align || "left", padding: "9px 12px", fontSize: 11,
                  fontWeight: 700, letterSpacing: 0.6, color: "#7C7259",
                  textTransform: "uppercase", borderBottom: "2px solid #E6DFCB",
                  whiteSpace: "nowrap",
                }}
              >
                {c.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr
              key={row[keyField] || i}
              onClick={onRowClick ? () => onRowClick(row) : undefined}
              style={{
                cursor: onRowClick ? "pointer" : "default",
                background: i % 2 === 0 ? "#FFFFFF" : "#FBF9F1",
              }}
              onMouseEnter={(e) => (e.currentTarget.style.background = "#F3EDD8")}
              onMouseLeave={(e) => (e.currentTarget.style.background = i % 2 === 0 ? "#FFFFFF" : "#FBF9F1")}
            >
              {columns.map((c) => (
                <td
                  key={c.key}
                  style={{
                    padding: "10px 12px", borderBottom: "1px solid #F0EBDA",
                    color: "#3B4239", textAlign: c.align || "left",
                    fontFamily: c.mono ? "'IBM Plex Mono', monospace" : "'Inter', sans-serif",
                    fontVariantNumeric: c.mono ? "tabular-nums" : "normal",
                  }}
                >
                  {c.render ? c.render(row) : row[c.key]}
                </td>
              ))}
            </tr>
          ))}
          {rows.length === 0 && (
            <tr>
              <td colSpan={columns.length} style={{ padding: "22px 12px", color: "#9C8F6E", textAlign: "center", fontSize: 13 }}>
                No matching records.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

function KpiCard({ label, value, sub, icon: Icon, accent }) {
  return (
    <div
      style={{
        background: "#FFFFFF", border: "1px solid #E6DFCB", borderRadius: 10,
        padding: "18px 20px", flex: 1, minWidth: 180,
        boxShadow: "0 1px 2px rgba(41,33,15,0.04)",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: 0.6, color: "#7C7259", textTransform: "uppercase" }}>
          {label}
        </div>
        <div style={{ width: 30, height: 30, borderRadius: 8, background: accent + "1A", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Icon size={15} color={accent} />
        </div>
      </div>
      <div style={{ fontFamily: "'Fraunces', serif", fontSize: 30, fontWeight: 600, color: "#26332C", marginTop: 8 }}>
        {value}
      </div>
      {sub && <div style={{ fontSize: 12, color: "#8C8264", marginTop: 3 }}>{sub}</div>}
    </div>
  );
}

function Modal({ title, onClose, onDelete, children, width = 560 }) {
  return (
    <div
      style={{
        position: "fixed", inset: 0, background: "rgba(38,51,44,0.45)", zIndex: 50,
        display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
      }}
      onClick={onClose}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#FDFBF4", borderRadius: 12, width, maxWidth: "100%",
          maxHeight: "88vh", overflowY: "auto", boxShadow: "0 24px 60px rgba(20,20,10,0.35)",
          border: "1px solid #E6DFCB",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "16px 22px", borderBottom: "1px solid #EEE8D6", position: "sticky", top: 0, background: "#FDFBF4" }}>
          <h3 style={{ margin: 0, fontFamily: "'Fraunces', serif", fontSize: 18, fontWeight: 600, color: "#26332C" }}>{title}</h3>
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            {onDelete && (
              <button
                onClick={onDelete}
                title="Delete"
                style={{ background: "none", border: "none", cursor: "pointer", color: "#8A2E24", padding: 4, display: "flex" }}
              >
                <Trash2 size={16} />
              </button>
            )}
            <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: "#7C7259", padding: 4, display: "flex" }}>
              <X size={18} />
            </button>
          </div>
        </div>
        <div style={{ padding: 22 }}>{children}</div>
      </div>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{ fontSize: 11.5, fontWeight: 700, color: "#7C7259", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 5 }}>
        {label}
      </div>
      {children}
    </div>
  );
}

