function Btn({ children, onClick, variant = "primary", icon: Icon, style }) {
  const variants = {
    primary: { background: "#2F4A3C", color: "#FBF6E4", border: "1px solid #2F4A3C" },
    ghost: { background: "transparent", color: "#2F4A3C", border: "1px solid #C9BE9C" },
    gold: { background: "#B8912A", color: "#FFF9E9", border: "1px solid #B8912A" },
  };
  return (
    <button
      onClick={onClick}
      style={{
        display: "inline-flex", alignItems: "center", gap: 7, padding: "8px 15px",
        borderRadius: 7, fontSize: 13.5, fontWeight: 600, cursor: "pointer",
        fontFamily: "'Inter', sans-serif", ...variants[variant], ...style,
      }}
    >
      {Icon && <Icon size={14} />}
      {children}
    </button>
  );
}

