/* ------------------------------------------------------------------ */
/* Generic master list page                                            */
/* ------------------------------------------------------------------ */

function MasterListPage({ eyebrow, title, columns, data, searchKeys, addLabel, renderAddForm, keyField = "name" }) {
  const [q, setQ] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const [editingRow, setEditingRow] = useState(null);
  const [rows, setRows] = useState(data);

  const filtered = useMemo(() => {
    if (!q.trim()) return rows;
    const needle = q.toLowerCase();
    return rows.filter((r) => searchKeys.some((k) => String(r[k] ?? "").toLowerCase().includes(needle)));
  }, [q, rows]);

  const openAdd = () => { setEditingRow(null); setModalOpen(true); };
  const openEdit = (row) => { setEditingRow(row); setModalOpen(true); };
  const closeModal = () => { setModalOpen(false); setEditingRow(null); };

  const handleSave = (updatedRow) => {
    if (editingRow) {
      setRows(rows.map((r) => (r[keyField] === editingRow[keyField] ? updatedRow : r)));
    } else {
      setRows([updatedRow, ...rows]);
    }
    closeModal();
  };

  const handleDelete = () => {
    setRows(rows.filter((r) => r[keyField] !== editingRow[keyField]));
    closeModal();
  };

  return (
    <SectionCard
      eyebrow={eyebrow}
      title={title}
      right={
        <div style={{ display: "flex", gap: 10 }}>
          <SearchBox value={q} onChange={setQ} placeholder={`Search ${title.toLowerCase()}\u2026`} />
          {addLabel && <Btn icon={PlusCircle} onClick={openAdd}>{addLabel}</Btn>}
        </div>
      }
    >
      <div style={{ fontSize: 12, color: "#8C8264", marginBottom: 12 }}>
        {filtered.length} of {rows.length} records{renderAddForm ? " \u00b7 click a row to edit" : ""}
      </div>
      <Table columns={columns} rows={filtered} keyField={keyField} onRowClick={renderAddForm ? openEdit : undefined} />
      {modalOpen && (
        <Modal
          title={editingRow ? `Edit ${title}` : addLabel}
          onClose={closeModal}
          onDelete={editingRow ? handleDelete : undefined}
        >
          {renderAddForm ? renderAddForm(handleSave, editingRow) : null}
        </Modal>
      )}
    </SectionCard>
  );
}

/* ------------------------------------------------------------------ */
/* Company master                                                      */
/* ------------------------------------------------------------------ */

function CompanyPage() {
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState(COMPANY);
  const set = (path, value) => {
    setForm((prev) => {
      const next = JSON.parse(JSON.stringify(prev));
      const keys = path.split(".");
      let obj = next;
      for (let i = 0; i < keys.length - 1; i++) obj = obj[keys[i]];
      obj[keys[keys.length - 1]] = value;
      return next;
    });
  };
  const fieldProps = (path, value) => editing
    ? { value, onChange: (e) => set(path, e.target.value) }
    : { readOnly: true, value };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <SectionCard
        eyebrow="Enterprise"
        title="Company details"
        right={
          editing ? (
            <div style={{ display: "flex", gap: 10 }}>
              <Btn variant="ghost" onClick={() => { setForm(COMPANY); setEditing(false); }}>Cancel</Btn>
              <Btn onClick={() => setEditing(false)}>Save Changes</Btn>
            </div>
          ) : (
            <Btn variant="ghost" onClick={() => setEditing(true)}>Edit</Btn>
          )
        }
      >
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
          <Field label="Company Name"><input style={inputStyle} {...fieldProps("name", form.name)} /></Field>
          <Field label="Trade Name"><input style={inputStyle} {...fieldProps("tradeName", form.tradeName)} /></Field>
          <Field label="Registration Number"><input style={inputStyle} {...fieldProps("regNo", form.regNo)} /></Field>
          <Field label="Company Code"><input style={inputStyle} {...fieldProps("code", form.code)} /></Field>
          <Field label="Website"><input style={inputStyle} {...fieldProps("web", form.web)} /></Field>
          <Field label="Registered Address">
            {editing ? (
              <textarea style={{ ...inputStyle, resize: "none", height: 60 }} value={form.address} onChange={(e) => set("address", e.target.value)} />
            ) : (
              <textarea readOnly style={{ ...inputStyle, resize: "none", height: 60 }} value={form.address} />
            )}
          </Field>
        </div>
      </SectionCard>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
        <SectionCard eyebrow="Statutory" title="PF details">
          <Field label="PF Establishment Code"><input style={inputStyle} {...fieldProps("pf.code", form.pf.code)} /></Field>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
            <Field label="Own Contribution EPF %"><input style={inputStyle} {...fieldProps("pf.own", form.pf.own)} /></Field>
            <Field label="EPF %"><input style={inputStyle} {...fieldProps("pf.epf", form.pf.epf)} /></Field>
            <Field label="Company Contribution FPF %"><input style={inputStyle} {...fieldProps("pf.company", form.pf.company)} /></Field>
            <Field label="FPF %"><input style={inputStyle} {...fieldProps("pf.fpf", form.pf.fpf)} /></Field>
          </div>
        </SectionCard>
        <SectionCard eyebrow="Statutory" title="ESI details">
          <Field label="ESI Establishment Code"><input style={inputStyle} {...fieldProps("esi.code", form.esi.code)} /></Field>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
            <Field label="ESI Ceiling Amount"><input style={inputStyle} {...fieldProps("esi.ceiling", form.esi.ceiling)} /></Field>
            <Field label="ESI Contribution %"><input style={inputStyle} {...fieldProps("esi.contribution", form.esi.contribution)} /></Field>
            <Field label="Employer %"><input style={inputStyle} {...fieldProps("esi.employer", form.esi.employer)} /></Field>
          </div>
        </SectionCard>
      </div>

      <SectionCard eyebrow="Other statutory" title="Cess, bonus & superannuation">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 14 }}>
          <Field label="Education Cess %"><input style={inputStyle} {...fieldProps("others.eduCess", form.others.eduCess)} /></Field>
          <Field label="Bonus Ceiling Amount"><input style={inputStyle} {...fieldProps("others.bonusCeiling", form.others.bonusCeiling)} /></Field>
          <Field label="FPF Not-Eligible Age (yrs)"><input style={inputStyle} {...fieldProps("others.fpfNotEligibleYears", form.others.fpfNotEligibleYears)} /></Field>
        </div>
      </SectionCard>
      {!editing && (
        <div style={{ fontSize: 12, color: "#8C8264" }}>Click <strong>Edit</strong> above to see the data-entry state of this screen.</div>
      )}
    </div>
  );
}

