function VariableEntryPage({ mode }) {
  const isEarn = mode === "earnings";
  const options = isEarn ? EARNINGS.filter(e => e.type === "Variable").map(e => e.name) : DEDUCTIONS.filter(d => d.type === "Variable").map(d => d.name);
  const [type, setType] = useState(options[0]);
  const [amounts, setAmounts] = useState(() => Object.fromEntries(EMPLOYEES.slice(0, 9).map((e) => [e.code, ""])));

  const total = Object.values(amounts).reduce((s, v) => s + (parseFloat(v) || 0), 0);

  return (
    <SectionCard
      eyebrow={`Transactions \u00b7 August 2026`}
      title={isEarn ? "Variable earnings entry" : "Variable deductions entry"}
      right={
        <select value={type} onChange={(e) => setType(e.target.value)} style={{ ...inputStyle, width: 220 }}>
          {options.map((o) => <option key={o}>{o}</option>)}
        </select>
      }
    >
      <div style={{ display: "flex", gap: 20, marginBottom: 16, fontSize: 12.5, color: "#5B5240", flexWrap: "wrap" }}>
        <span><strong>Division</strong> Glendale Division</span>
        <span><strong>Category</strong> Workers</span>
        <span><strong>{isEarn ? "Earning" : "Deduction"} Type</strong> {type}</span>
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13.5 }}>
          <thead>
            <tr>
              <th style={{ textAlign: "left", padding: "9px 12px", fontSize: 11, fontWeight: 700, color: "#7C7259", textTransform: "uppercase", borderBottom: "2px solid #E6DFCB" }}>Code</th>
              <th style={{ textAlign: "left", padding: "9px 12px", fontSize: 11, fontWeight: 700, color: "#7C7259", textTransform: "uppercase", borderBottom: "2px solid #E6DFCB" }}>Employee</th>
              <th style={{ textAlign: "right", padding: "9px 12px", fontSize: 11, fontWeight: 700, color: "#7C7259", textTransform: "uppercase", borderBottom: "2px solid #E6DFCB" }}>Amount (\u20b9)</th>
            </tr>
          </thead>
          <tbody>
            {EMPLOYEES.slice(0, 9).map((e, i) => (
              <tr key={e.code} style={{ background: i % 2 === 0 ? "#FFFFFF" : "#FBF9F1" }}>
                <td style={{ padding: "8px 12px", fontFamily: "'IBM Plex Mono', monospace", borderBottom: "1px solid #F0EBDA" }}>{e.code}</td>
                <td style={{ padding: "8px 12px", borderBottom: "1px solid #F0EBDA" }}>{e.name}</td>
                <td style={{ padding: "6px 12px", borderBottom: "1px solid #F0EBDA", textAlign: "right" }}>
                  <input
                    value={amounts[e.code]}
                    onChange={(ev) => setAmounts({ ...amounts, [e.code]: ev.target.value })}
                    placeholder="0.00"
                    style={{ ...inputStyle, textAlign: "right", width: 120, fontFamily: "'IBM Plex Mono', monospace", padding: "6px 10px" }}
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "center", gap: 14, marginTop: 16, paddingTop: 14, borderTop: "1px solid #EEE8D6" }}>
        <span style={{ fontSize: 12.5, color: "#7C7259", fontWeight: 700, textTransform: "uppercase" }}>Total Amount</span>
        <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 19, fontWeight: 700, color: "#26332C" }}>
          {"\u20b9 " + total.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
        </span>
        <Btn>Save Entries</Btn>
      </div>
    </SectionCard>
  );
}

