function GradeLevelPage() {
  const [grades, setGrades] = useState(GRADES.map((g) => ({ name: g })));
  const [levels, setLevels] = useState(LEVELS.map((l) => ({ name: l })));
  const [gradeModal, setGradeModal] = useState(null); // { mode: "add" | "edit", row }
  const [levelModal, setLevelModal] = useState(null);

  const saveGrade = (row) => {
    if (gradeModal.mode === "edit") {
      setGrades(grades.map((g) => (g.name === gradeModal.row.name ? row : g)));
    } else {
      setGrades([row, ...grades]);
    }
    setGradeModal(null);
  };
  const deleteGrade = () => {
    setGrades(grades.filter((g) => g.name !== gradeModal.row.name));
    setGradeModal(null);
  };
  const saveLevel = (row) => {
    if (levelModal.mode === "edit") {
      setLevels(levels.map((l) => (l.name === levelModal.row.name ? row : l)));
    } else {
      setLevels([row, ...levels]);
    }
    setLevelModal(null);
  };
  const deleteLevel = () => {
    setLevels(levels.filter((l) => l.name !== levelModal.row.name));
    setLevelModal(null);
  };

  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
      <SectionCard eyebrow="Masters" title="Grade" right={<Btn icon={PlusCircle} onClick={() => setGradeModal({ mode: "add" })}>New Grade</Btn>}>
        <div style={{ fontSize: 12, color: "#8C8264", marginBottom: 10 }}>Click a row to edit</div>
        <Table columns={[{ key: "name", label: "Grade Name" }]} rows={grades} keyField="name" onRowClick={(row) => setGradeModal({ mode: "edit", row })} />
        {gradeModal && (
          <Modal title={gradeModal.mode === "edit" ? "Edit Grade" : "New Grade"} onClose={() => setGradeModal(null)} onDelete={gradeModal.mode === "edit" ? deleteGrade : undefined}>
            <AddSingleFieldForm placeholder="e.g. Sr C Grade" label="Grade Name" onSave={saveGrade} initial={gradeModal.row} />
          </Modal>
        )}
      </SectionCard>
      <SectionCard eyebrow="Masters" title="Level" right={<Btn icon={PlusCircle} onClick={() => setLevelModal({ mode: "add" })}>New Level</Btn>}>
        <div style={{ fontSize: 12, color: "#8C8264", marginBottom: 10 }}>Click a row to edit</div>
        <Table columns={[{ key: "name", label: "Level Name" }]} rows={levels} keyField="name" onRowClick={(row) => setLevelModal({ mode: "edit", row })} />
        {levelModal && (
          <Modal title={levelModal.mode === "edit" ? "Edit Level" : "New Level"} onClose={() => setLevelModal(null)} onDelete={levelModal.mode === "edit" ? deleteLevel : undefined}>
            <AddSingleFieldForm placeholder="e.g. Hourly Rated" label="Level Name" onSave={saveLevel} initial={levelModal.row} />
          </Modal>
        )}
      </SectionCard>
    </div>
  );
}

